INPUT_MODE = 'sim'
DEMO_CONTROLS = True
NAMES = {'sample': 'sample', 'event': 'event', 'link': 'link', 'stats': 'stats', 'hb_ack': 'hb_ack', 'sync': 'sync', 'heartbeat': 'heartbeat', 'sim_set': 'sim_set'}             # Bridge names, from the compiler's bridge contract
U8, U16, U32 = 0xFF, 0xFFFF, 0xFFFFFFFF
RESULTS = ("applied", "refused", "forced", "failsafe")
SIM_RESEND_S = 0.5
PUSH_S = 0.2
HISTORY = 600                 # samples kept for a page opened mid-run (60 s at 100 ms)
LOG_KEEP = 200


def _u(v, limit):
    """Range-check an integer before it crosses the Bridge (the MCU truncates silently, §19)."""
    v = int(v)
    if not 0 <= v <= limit:
        raise ValueError(f"{v} out of range 0..{limit}")
    return v


class Brain:
    """All Linux-side logic; I/O goes through the callables, so tests can drive it."""

    def __init__(self, table, notify, push, emit, clock):
        self.t = table
        self.notify, self.push, self.emit, self.clock = notify, push, emit, clock
        self.side = LinuxSide(table)
        self.H = table["heartbeat_ms"] / 1000.0
        n_s = len(table["sensors"])
        self.codes = [0] * n_s
        self.have_sample = False
        self.last_t = 0
        self.cur = [a["init"] for a in table["actuators"]]
        self.link_up = False
        self.stats = {"overruns": 0, "max_pass_us": 0, "faults": 0}
        self.sent_at = {}
        self.rtts = deque(maxlen=200)
        self.history = deque(maxlen=HISTORY)
        self.log = deque(maxlen=LOG_KEEP)
        self.paused_until = 0.0
        self.last_beat_mono = None
        self.last_seq = 0
        self.led = False
        self.sim = list(table["sim_init"])          # same start values as the MCU (SENS_INIT)
        self.sim_dirty = False
        self.last_sim_send = 0.0
        self.last_push = 0.0
        self.refused_until = 0.0
        self.cached = {"state": None, "history": [], "log": []}
        self.cached_at = -1e9

    # -- helpers ------------------------------------------------------------------------------
    def paused(self, now):
        return now < self.paused_until

    def _beat(self, hb, now):
        seq, mask, ack = hb
        self.notify(NAMES["heartbeat"], _u(seq, U32), _u(mask, U32), _u(ack, U32))
        self.sent_at[seq] = now
        if len(self.sent_at) > 500:
            self.sent_at.pop(next(iter(self.sent_at)))
        self.last_beat_mono = now
        self.last_seq = seq
        self.led = not self.led
        if Leds is not None:
            try:
                Leds.set_led1_color(False, self.led, False)
            except Exception:  # noqa: BLE001
                pass

    def _record(self, entry):
        self.log.append(entry)
        self.emit(entry["line"])
        self.push("event", entry)

    # -- messages from the MCU ----------------------------------------------------------------
    def on_sample(self, t, codes, now):
        codes = [int(c) for c in codes][: len(self.codes)]
        self.codes = codes
        self.have_sample = True
        self.last_t = int(t)
        self.history.append([int(t)] + codes + list(self.cur))   # page: chart lines and ON bands
        if self.paused(now):
            return
        hb, fired, reset = self.side.on_sample(int(t), codes)
        if reset:
            self._record({"kind": "I", "t": int(t), "line": f"I,{int(t)},mcu reset", "text": "MCU reset detected"})
        for rid in fired:
            rule = self.t["rules"][rid]
            text = rule["action"][1]
            self._record({"kind": "NT", "t": int(t), "rule": rule["name"], "text": text,
                          "line": f'NT,{int(t)},{rule["name"]},"' + text.replace('"', '""') + '"'})
        if hb is not None:
            self._beat(hb, now)

    def on_event(self, t, act, state, src, result, detail):
        act, state, src, result, detail = int(act), int(state), int(src), int(result), int(detail)
        if src == 0xFF:
            src_name = "FAILSAFE"
        elif src >= 0xF0:
            src_name = f"ENSURE#{src - 0xF0 + 1}"
        else:
            src_name = self.t["rules"][src]["name"]
        res = RESULTS[result]
        det = "-" if detail == 0xFF else f"never#{detail + 1}"
        name = self.t["actuators"][act]["name"]
        st = "ON" if state else "OFF"
        if res != "refused":
            self.cur[act] = state
        else:
            self.refused_until = self.clock() + 1.0
        self._record({"kind": "EV", "t": int(t), "act": name, "state": st, "src": src_name, "result": res,
                      "detail": det, "line": f"EV,{int(t)},{name},{st},{src_name},{res},{det}"})

    def on_link(self, t, up):
        self.link_up = bool(up)
        word = "UP" if up else "DOWN"
        self._record({"kind": "LK", "t": int(t), "up": self.link_up, "line": f"LK,{int(t)},{word}"})

    def on_stats(self, t, overruns, max_pass_us, faults):
        self.stats = {"overruns": int(overruns), "max_pass_us": int(max_pass_us), "faults": int(faults)}
        self.emit(f"ST,{int(t)},{int(overruns)},{int(max_pass_us)},{int(faults)}")

    def on_hb_ack(self, seq, now):
        sent = self.sent_at.pop(int(seq), None)
        if sent is not None:
            self.rtts.append((now - sent) * 1000.0)

    def on_sync(self, t, iteration):
        self.side.reset()
        self._record({"kind": "SY", "t": int(t), "line": f"SY,{int(t)},{int(iteration)}",
                      "text": f"scenario start #{int(iteration)}"})

    # -- messages from the page ---------------------------------------------------------------
    def set_slider(self, sensor, code):
        i = int(sensor)
        if not 0 <= i < len(self.sim):
            return
        c = max(0, min(int(code), self.t["sensors"][i]["adc_max"]))
        self.sim[i] = c
        self.sim_dirty = True

    def note(self, text):
        """An information line (I) for stdout and the page log, stamped with the board time."""
        self._record({"kind": "I", "t": self.last_t, "text": text, "line": f"I,{self.last_t},{text}"})

    def pause(self, seconds, now):
        self.paused_until = now + max(0.0, min(float(seconds), 60.0))

    def resume(self):
        self.paused_until = 0.0

    # -- periodic work ------------------------------------------------------------------------
    def tick(self, now):
        paused = self.paused(now)
        if not paused and self.have_sample and self.last_beat_mono is not None \
                and now - self.last_beat_mono >= self.H:
            self._beat(self.side.beat(self.last_t), now)        # samples stopped: ack goes stale
        if INPUT_MODE == "sim" and (self.sim_dirty or now - self.last_sim_send >= SIM_RESEND_S):
            for i, c in enumerate(self.sim):
                self.notify(NAMES["sim_set"], _u(i, U8), _u(c, U16))
            self.sim_dirty = False
            self.last_sim_send = now
        if now - self.last_push >= PUSH_S:
            self.last_push = now
            self.push("state", self.state(now))
        if now - self.cached_at >= 1.0:
            self.cached_at = now
            self.cached = json.loads(json.dumps(self.snapshot(now)))

    def firing(self):
        out = []
        windows = self.side.engine.windows
        for i, r in enumerate(self.t["rules"]):
            if r["placement"] == "LINUX":
                if r["mask_bit"] is not None:
                    out.append(1 if (self.side.engine.mask >> r["mask_bit"]) & 1 else 0)
                else:
                    out.append(1 if tests_hold(r["tests"], self.codes, windows) else 0)
            elif all(t[0] == "range" and t[1] == "raw" for t in r["tests"]):
                out.append(1 if tests_hold(r["tests"], self.codes, {}) else 0)
            else:
                out.append(0)
        return out

    def state(self, now):
        fire = self.firing()
        ensure = any(all(t[0] == "range" and t[1] == "raw" for t in e["tests"])
                     and tests_hold(e["tests"], self.codes, {}) for e in self.t["ensures"])
        status = {"failsafe": (not self.link_up) and bool(self.t["fs"]), "ensure": ensure,
                  "refused": now < self.refused_until, "beat": self.led, "bridge_failed": False}
        n_bars = len(self.t["matrix"]["bars"])
        px = matrix_frame(self.t["matrix"], self.codes[:n_bars], fire, self.cur, status,
                          (self.last_t // self.t["sample_ms"]) & 1)
        r = sorted(self.rtts)
        return {
            "t": self.last_t, "codes": self.codes, "cur": self.cur, "link_up": self.link_up,
            "firing": fire, "mask": self.side.engine.mask, "paused": self.paused(now),
            "paused_left": max(0.0, round(self.paused_until - now, 1)), "seq": self.last_seq,
            "beat_age_ms": None if self.last_beat_mono is None else int((now - self.last_beat_mono) * 1000),
            "stats": self.stats, "sim": self.sim, "matrix": px,
            "rtt": {"n": len(r), "median": round(statistics.median(r), 1) if r else None,
                    "max": round(r[-1], 1) if r else None},
        }

    def snapshot(self, now):
        return {"state": self.state(now), "history": list(self.history), "log": list(self.log)}


# -- wiring on the board ---------------------------------------------------------------------------
inbox = queue.Queue(maxsize=1024)
dropped = [0]


def _put(item):
    try:
        inbox.put_nowait(item)
    except queue.Full:
        try:
            inbox.get_nowait()
        except queue.Empty:
            pass
        dropped[0] += 1
        inbox.put_nowait(item)


ui = WebUI()


def _push(kind, data):
    try:
        ui.send_message(kind, data)
    except Exception as exc:  # noqa: BLE001
        print("page push failed:", repr(exc), flush=True)


def _emit(line):
    print(line, flush=True)


brain = Brain(TABLE, Bridge.notify, _push, _emit, time.monotonic)

Bridge.provide(NAMES["sample"], lambda t, *codes: _put(("sample", t, codes)))
Bridge.provide(NAMES["event"], lambda t, a, s, src, res, det: _put(("event", t, a, s, src, res, det)))
Bridge.provide(NAMES["link"], lambda t, up: _put(("link", t, up)))
Bridge.provide(NAMES["stats"], lambda t, ov, mx, faults: _put(("stats", t, ov, mx, faults)))
Bridge.provide(NAMES["hb_ack"], lambda seq: _put(("hb_ack", seq, time.monotonic())))
Bridge.provide(NAMES["sync"], lambda t, it: _put(("sync", t, it)))


def _on_ui(kind, data):
    _put(("ui", kind, data if isinstance(data, dict) else {}))


ui.on_message("sim_set", lambda sid, data: _on_ui("sim_set", data))
ui.on_message("pause", lambda sid, data: _on_ui("pause", data))
ui.on_message("resume", lambda sid, data: _on_ui("resume", data))
ui.on_connect(lambda sid: _put(("connect", sid)))                 # snapshot built in loop()
ui.expose_api("GET", "/api/state", lambda: brain.cached)          # copy refreshed in tick()


def _dispatch(msg, now):
    kind = msg[0]
    if kind == "sample":
        brain.on_sample(msg[1], msg[2], now)
    elif kind == "event":
        brain.on_event(*msg[1:])
    elif kind == "link":
        brain.on_link(*msg[1:])
    elif kind == "stats":
        brain.on_stats(*msg[1:])
    elif kind == "hb_ack":
        brain.on_hb_ack(msg[1], msg[2])
    elif kind == "sync":
        brain.on_sync(*msg[1:])
    elif kind == "connect":
        ui.send_message("snapshot", brain.snapshot(now), msg[1])
    elif kind == "ui":
        _, what, data = msg
        if what == "sim_set":
            brain.set_slider(data.get("sensor", -1), data.get("code", 0))
        elif what == "pause" and DEMO_CONTROLS:
            brain.pause(data.get("seconds", 10), now)
            brain.note("Linux rule engine paused from the page: heartbeats stop")
        elif what == "resume":
            brain.resume()
            brain.note("Linux rule engine resumed")


def loop():
    try:
        now = time.monotonic()
        for _ in range(64):
            try:
                msg = inbox.get_nowait()
            except queue.Empty:
                break
            try:
                _dispatch(msg, now)
            except Exception as exc:  # noqa: BLE001 - one bad message never stops the brain
                print("iotc: message error:", repr(exc), flush=True)
        brain.tick(now)
    except Exception as exc:  # noqa: BLE001
        print("iotc: loop error:", repr(exc), flush=True)
    time.sleep(0.005)


print(f"iotc Linux side started: {len(TABLE['rules'])} rules, input {INPUT_MODE}; page on port 7000", flush=True)
App.run(user_loop=loop)
